namespace Primify.Generators;

/// <summary>
/// Renders the generated source text for a <see cref="PrimifyModel"/>: the wrapper declaration and its
/// members. Serializer adapters (LiteDB, Newtonsoft.Json) are rendered separately per compilation by
/// <see cref="SerializerAdapterRenderer"/>, only when the consumer references those packages.
/// </summary>
/// <remarks>
/// Everything the generated file references is <c>global::</c>-qualified, so the file binds no matter
/// what namespaces or type aliases the consumer declares. The generated file therefore carries no
/// <c>using</c> directives — an unused <c>using</c> would surface as CS8019 in the consuming project.
/// </remarks>
internal static class PrimifyRenderer
{
    private const string MaybeNullWhen = "[global::System.Diagnostics.CodeAnalysis.MaybeNullWhen(false)] ";

    public static string Render(PrimifyModel model)
    {
        var writer = new SourceWriter();
        writer.WriteLine("// <auto-generated/>");
        writer.WriteLine("#nullable enable");
        writer.BlankLine();

        if (model.ContainingTypes.IsEmpty)
        {
            if (!model.IsGlobalNamespace)
            {
                writer.WriteLine($"namespace {model.Namespace};");
                writer.BlankLine();
            }

            RenderWrapper(writer, model);
            return writer.ToString();
        }

        var closeNamespace = false;
        if (!model.IsGlobalNamespace)
        {
            writer.WriteLine($"namespace {model.Namespace}");
            writer.OpenBrace();
            closeNamespace = true;
        }

        foreach (var containingType in model.ContainingTypes)
        {
            writer.WriteLine(containingType.Declaration);
            writer.OpenBrace();
        }

        RenderWrapper(writer, model);

        for (var index = model.ContainingTypes.Items.Length - 1; index >= 0; index--)
        {
            writer.CloseBrace();
        }

        if (closeNamespace)
        {
            writer.CloseBrace();
        }

        return writer.ToString();
    }

    private static void RenderWrapper(SourceWriter writer, PrimifyModel model)
    {
        var name = model.ClassName;
        var type = model.WrappedTypeQualified!;
        var modifier = model.IsValueType ? "readonly " : string.Empty;

        writer.WriteLine("[global::System.Diagnostics.DebuggerDisplay(\"{Value}\")]");
        writer.WriteLine($"[global::System.Text.Json.Serialization.JsonConverter(typeof(global::Primify.Converters.SystemTextJsonConverter<{name}, {type}>))]");
        if (model.NewtonsoftAvailable)
        {
            writer.WriteLine($"[global::Newtonsoft.Json.JsonConverter(typeof(global::Primify.Converters.NewtonsoftJsonConverter<{name}, {type}>))]");
        }

        writer.WriteLine($"{modifier}partial {model.Keyword} {name} : global::Primify.IPrimify<{name}, {type}>, global::System.IEquatable<{name}>");
        writer.OpenBrace();
        writer.WriteLine("/// <summary>Gets the wrapped primitive value.</summary>");
        writer.WriteLine($"public {type} Value {{ get; }}");
        writer.BlankLine();
        writer.WriteLine($"private {name}({type} value) => Value = value;");
        writer.BlankLine();
        AppendFrom(writer, model);
        writer.BlankLine();
        AppendTryFrom(writer, model);
        writer.BlankLine();
        AppendPrimitiveConversions(writer, model);

        if (!model.IsRecord)
        {
            var toStringBody = model.WrappedTypeIsReferenceType
                ? "Value?.ToString() ?? string.Empty"
                : "Value.ToString()";
            writer.BlankLine();
            writer.WriteLine("/// <summary>Returns the string form of the underlying value.</summary>");
            writer.WriteLine($"public override string ToString() => {toStringBody};");
        }

        WriteEqualityMembers(writer, model);
        writer.CloseBrace();
    }

    private static void AppendFrom(SourceWriter writer, PrimifyModel model)
    {
        var name = model.ClassName;
        var type = model.WrappedTypeQualified!;

        writer.WriteLine("/// <summary>");
        writer.WriteLine("/// Creates a validated instance by running the declaring type's Normalize hook");
        writer.WriteLine("/// followed by its Validate hook.");
        writer.WriteLine("/// </summary>");
        writer.WriteLine("/// <param name=\"value\">The primitive value to wrap.</param>");
        writer.WriteLine("/// <returns>The validated wrapper instance.</returns>");
        writer.WriteLine("/// <exception cref=\"global::System.ArgumentException\">Thrown when validation rejects the value; also covers ArgumentNullException for null reference-type values.</exception>");
        writer.WriteLine($"public static {name} From({type} value)");
        writer.OpenBrace();

        if (model.WrappedTypeIsReferenceType)
        {
            writer.WriteLine("if (value is null)");
            writer.OpenBrace();
            writer.WriteLine("throw new global::System.ArgumentNullException(nameof(value));");
            writer.CloseBrace();
            writer.BlankLine();
        }

        writer.WriteLine("var processedValue = value;");
        if (model.HasNormalize)
        {
            writer.WriteLine("processedValue = Normalize(processedValue);");
            if (model.WrappedTypeIsReferenceType)
            {
                writer.WriteLine("if (processedValue is null)");
                writer.OpenBrace();
                writer.WriteLine("throw new global::System.ArgumentNullException(nameof(value), \"Normalize returned null.\");");
                writer.CloseBrace();
            }
        }

        if (model.HasValidate)
        {
            writer.WriteLine("Validate(processedValue);");
        }

        writer.WriteLine($"return new {name}(processedValue);");
        writer.CloseBrace();
    }

    private static void AppendTryFrom(SourceWriter writer, PrimifyModel model)
    {
        var name = model.ClassName;
        var type = model.WrappedTypeQualified!;

        writer.WriteLine("/// <summary>");
        writer.WriteLine("/// Non-throwing alternative to <see cref=\"From\"/>. Applies the same Normalize and");
        writer.WriteLine("/// Validate hooks; returns false when <see cref=\"From\"/> throws, whatever the exception type.");
        writer.WriteLine("/// </summary>");
        writer.WriteLine("/// <param name=\"value\">The primitive value to wrap.</param>");
        writer.WriteLine(model.IsValueType
            ? "/// <param name=\"result\">The validated instance, or default when creation fails.</param>"
            : "/// <param name=\"result\">The validated instance on success, or null when creation fails.</param>");
        writer.WriteLine("/// <returns>true when the value passed validation; otherwise false.</returns>");
        var resultNullability = model.IsValueType ? string.Empty : MaybeNullWhen;
        writer.WriteLine($"public static bool TryFrom({type} value, {resultNullability}out {name} result)");
        writer.OpenBrace();
        writer.WriteLine("try");
        writer.OpenBrace();
        writer.WriteLine("result = From(value);");
        writer.WriteLine("return true;");
        writer.CloseBrace();
        writer.WriteLine("catch (global::System.Exception)");
        writer.OpenBrace();
        writer.WriteLine("result = default!;");
        writer.WriteLine("return false;");
        writer.CloseBrace();
        writer.CloseBrace();
    }

    private static void AppendPrimitiveConversions(SourceWriter writer, PrimifyModel model)
    {
        var name = model.ClassName;
        var type = model.WrappedTypeQualified!;

        // primitive -> wrapper runs normalization/validation and can throw; it must be explicit.
        writer.WriteLine("/// <summary>Wraps the primitive through the same normalize/validate pipeline as <see cref=\"From\"/>.</summary>");
        writer.WriteLine("/// <param name=\"value\">The primitive value to wrap.</param>");
        writer.WriteLine($"public static explicit operator {name}({type} value) => From(value);");
        writer.WriteLine("/// <summary>Returns the underlying primitive value.</summary>");
        writer.WriteLine("/// <exception cref=\"global::System.ArgumentNullException\">The wrapper reference is null.</exception>");
        if (model.IsValueType)
        {
            writer.WriteLine("/// <param name=\"value\">The wrapper instance.</param>");
            writer.WriteLine($"public static implicit operator {type}({name} value) => value.Value;");
        }
        else
        {
            writer.WriteLine("/// <param name=\"value\">The wrapper instance.</param>");
            writer.WriteLine($"public static implicit operator {type}({name}? value) => value is null ? throw new global::System.ArgumentNullException(nameof(value)) : value.Value;");
        }
    }

    private static void WriteEqualityMembers(SourceWriter writer, PrimifyModel model)
    {
        // For record types, let the compiler generate optimized equality.
        if (model.IsRecord)
        {
            return;
        }

        var name = model.ClassName;
        var (equalsExpr, hashCodeExpr) = GetEqualityExpressions(model.EqualityStrategy, model.WrappedTypeQualified!);

        writer.BlankLine();

        if (model.IsValueType)
        {
            writer.WriteLine("/// <summary>Determines whether the specified object wraps an equal value.</summary>");
            writer.WriteLine($"public override bool Equals(object? obj) => obj is {name} other && Equals(other);");
            writer.BlankLine();
            writer.WriteLine("/// <summary>Determines whether the other instance wraps an equal value.</summary>");
            writer.WriteLine($"public bool Equals({name} other)");
            writer.OpenBrace();
            writer.WriteLine($"return {equalsExpr("Value", "other.Value")};");
            writer.CloseBrace();
            writer.BlankLine();
            writer.WriteLine("/// <summary>Returns a hash code based on the underlying value.</summary>");
            writer.WriteLine($"public override int GetHashCode() => {hashCodeExpr("Value")};");
            writer.BlankLine();
            writer.WriteLine("/// <summary>Compares two instances by their underlying values.</summary>");
            writer.WriteLine($"public static bool operator ==({name} left, {name} right) => left.Equals(right);");
            writer.BlankLine();
            writer.WriteLine("/// <summary>Compares two instances by their underlying values.</summary>");
            writer.WriteLine($"public static bool operator !=({name} left, {name} right) => !(left == right);");
            return;
        }

        writer.WriteLine("/// <summary>Determines whether the specified object wraps an equal value.</summary>");
        writer.WriteLine($"public override bool Equals(object? obj) => obj is {name} other && Equals(other);");
        writer.BlankLine();
        writer.WriteLine("/// <summary>Determines whether the other instance wraps an equal value.</summary>");
        writer.WriteLine($"public bool Equals({name}? other)");
        writer.OpenBrace();
        writer.WriteLine("if (global::System.Object.ReferenceEquals(null, other)) return false;");
        writer.WriteLine("if (global::System.Object.ReferenceEquals(this, other)) return true;");
        writer.WriteLine($"return {equalsExpr("Value", "other.Value")};");
        writer.CloseBrace();
        writer.BlankLine();
        writer.WriteLine("/// <summary>Returns a hash code based on the underlying value.</summary>");
        writer.WriteLine($"public override int GetHashCode() => {hashCodeExpr("Value")};");
        writer.BlankLine();
        writer.WriteLine("/// <summary>Compares two instances by their underlying values; null references are equal only to each other.</summary>");
        writer.WriteLine($"public static bool operator ==({name}? left, {name}? right) => global::System.Object.ReferenceEquals(left, right) || (left is not null && left.Equals(right));");
        writer.BlankLine();
        writer.WriteLine("/// <summary>Compares two instances by their underlying values.</summary>");
        writer.WriteLine($"public static bool operator !=({name}? left, {name}? right) => !(left == right);");
    }

    private static (Func<string, string, string> equalsExpr, Func<string, string> hashCodeExpr) GetEqualityExpressions(
        EqualityStrategy strategy,
        string wrappedType) => strategy switch
        {
            EqualityStrategy.OrdinalString => (
                (left, right) => $"global::System.String.Equals({left}, {right}, global::System.StringComparison.Ordinal)",
                value => $"{value}?.GetHashCode() ?? 0"
            ),
            EqualityStrategy.Operator => (
                (left, right) => $"{left} == {right}",
                value => $"{value}.GetHashCode()"
            ),
            _ => (
                (left, right) => $"global::System.Collections.Generic.EqualityComparer<{wrappedType}>.Default.Equals({left}, {right})",
                value => $"global::System.Collections.Generic.EqualityComparer<{wrappedType}>.Default.GetHashCode({value})"
            )
        };
}
